package org.codex.nfsugpreview;
import java.nio.*;import java.nio.file.*;
public final class PcModelReferenceExport {
 static Path output;static StringBuilder manifest=new StringBuilder();static int total;
 static void save(String name,ByteBuffer bytes)throws Exception{byte[] data=new byte[bytes.remaining()];bytes.get(data);Files.write(output.resolve(name),data);}
 static void model(String name,ByteBuffer raw,NativeDrawBounds clip,int order)throws Exception{NativeModelMesh mesh=new NativeModelMesh(raw);FloatBuffer vertices=mesh.vertices();ByteBuffer floats=ByteBuffer.allocate(vertices.remaining()*4).order(ByteOrder.LITTLE_ENDIAN);while(vertices.hasRemaining())floats.putFloat(vertices.get());floats.flip();DoubleBuffer camera=mesh.cameraVertices();ByteBuffer doubles=ByteBuffer.allocate(camera.remaining()*8).order(ByteOrder.LITTLE_ENDIAN);while(camera.hasRemaining())doubles.putDouble(camera.get());doubles.flip();ByteBuffer planes=ByteBuffer.allocate(mesh.triangleVertices/3*44).order(ByteOrder.LITTLE_ENDIAN);for(int tri=0;tri<mesh.triangleVertices;tri+=3){NativeTexturePlane p=new NativeTexturePlane(mesh.vertices(),tri);planes.putFloat(p.x).putFloat(p.y);for(float v:p.base)planes.putFloat(v);for(float v:p.dx)planes.putFloat(v);for(float v:p.dy)planes.putFloat(v);}planes.flip();save(name+".model",raw.duplicate());save(name+".vertices",floats);save(name+".camera",doubles);save(name+".planes",planes);save(name+".rgba",mesh.texture());ByteBuffer indices=mesh.originalIndices();save(name+".indices",indices==null?ByteBuffer.allocate(0):indices);manifest.append(name).append(' ').append(mesh.width).append(' ').append(mesh.height).append(' ').append(mesh.sourceVertices).append(' ').append(mesh.sourceFaces).append(' ').append(mesh.triangleVertices).append(' ').append(indices==null?0:1).append(' ').append(clip.left).append(' ').append(clip.right).append(' ').append(clip.top).append(' ').append(clip.bottom).append(' ').append(order).append('\n');total++;}
 static ByteBuffer synthetic(double depth,boolean back,boolean hidden){ByteBuffer b=ByteBuffer.allocate(303).order(ByteOrder.LITTLE_ENDIAN);b.putInt(0,0x324d464e);b.putInt(4,3);b.putInt(8,1);b.putInt(12,3);b.putInt(16,2);b.putInt(20,2);b.putDouble(24,120);b.putDouble(32,80);b.putDouble(40,64);b.putDouble(96,2);b.putDouble(152,3);double[][] points={{-1,-1,hidden?.5:depth},{-1,1,hidden?.5:2},{1,-1,hidden?.5:2}};for(int i=0;i<3;i++)for(int j=0;j<3;j++)b.putDouble(160+i*24+j*8,points[i][j]);b.put(232,(byte)3);int[] ids=back?new int[]{0,2,1}:new int[]{0,1,2};for(int i=0;i<3;i++){b.putShort(233+i*2,(short)ids[i]);b.putDouble(239+i*16,i==2?1:0);b.putDouble(247+i*16,i==1?1:0);}for(int i=287;i<303;i++)b.put(i,(byte)(i%251));return b;}
 public static void main(String[] args)throws Exception{output=Paths.get(args[1]);Files.createDirectories(output);int frames=0;try(DirectoryStream<Path> paths=Files.newDirectoryStream(Paths.get(args[0]),"source-race-background-*.nrb")){for(Path path:paths){NativeSceneSnapshot scene=new NativeBackgroundScene(Files.readAllBytes(path)).sky.scene;for(int owner=0;owner<scene.geometryCount();owner++){NativeScenePacket packet=scene.geometry(owner);NativeWorldScene world=new NativeWorldScene(packet);for(int i=0;i<NativeModelMesh.modelCount(packet);i++){int order=-1;for(int command=0;command<world.commandCount();command++){NativeWorldScene.Command c=world.command(command);if(c.model&&c.index==i)order=command;}if(order<0)throw new AssertionError();model(scene.refresh+"-"+owner+"-"+i,NativeModelMesh.model(packet,i),NativeDrawBounds.command(world.bounds(),world.surfaceCount(),true,i),order);}}frames++;}}
 NativeDrawBounds full=new NativeDrawBounds(0,240,0,160);model("synthetic-near",synthetic(.5,false,false),full,-1);model("synthetic-back",synthetic(2,true,false),full,-1);model("synthetic-hidden",synthetic(2,false,true),full,-1);if(frames!=9)throw new AssertionError();Files.write(output.resolve("models.txt"),manifest.toString().getBytes("UTF-8"));System.out.println("PASS_PC_MODEL_JAVA_REFERENCE frames="+frames+" models="+total);}
}

